-- Seed: expand the past-paper library so students can find what they need
--
-- Gap analysis (before this migration):
--   • CAPS/NSC: only 186 papers, all 2016-2021, sourced from ageing Google
--     Drive links — nothing from 2022-2024, and thin subject coverage.
--   • Cambridge: no Commerce (7100), Combined Science (5129/0653),
--     Co-ordinated Sciences (0654) or ICT (0417) — high-demand subjects for
--     ZIMSEC-track and IGCSE learners.
--
-- What this adds (415 rows, EVERY URL machine-verified to serve %PDF bytes):
--   1. 265 official NSC (CAPS) Grade 12 papers, 2022-2024, November +
--      May/June sessions, linked straight from the Department of Basic
--      Education (education.gov.za) fileticket downloads — 20 subjects
--      including Mathematics, Physical Sciences, Life Sciences, Accounting,
--      English HL/FAL, Afrikaans HT/EAT, Geography, History, Business
--      Studies, Economics and technical subjects. Question papers paired
--      with marking guidelines (memos) wherever published.
--   2. 150 Cambridge O-Level/IGCSE papers 2018-2024 with mark schemes for
--      previously-missing syllabuses: Commerce 7100, Combined Science 5129
--      (O-Level) & 0653 (IGCSE), Co-ordinated Sciences 0654, ICT 0417.
--      Tagged ARRAY['O-Level','IGCSE','Form 4'] / ['IGCSE','O-Level','Form 4']
--      per the verified O-Level ≡ IGCSE equivalence encoded in
--      src/lib/personalization.ts.
--
-- Content spot-verified: random papers downloaded and first-page text
-- checked against the seeded subject/paper/session/year metadata.
-- Generated by scripts/build_dbe_paper_seed.py (DBE half).
-- Idempotent: NOT EXISTS guard on (title, curriculum).

INSERT INTO public.library_system_resources
  (title, kind, subject, topic, curriculum, grade_levels, pdf_url, video_url,
   thumbnail_url, description, paper_year, paper_session, paper_number,
   marking_scheme_url, rights_note)
